{
 "id": "SG8-F-LIUBEI",
 "entity_id": "sanguo-faction-liubei",
 "title": "不是围在一个人的身后的同一心思",
 "base_record": {
  "content_ref": "数据/世界资料.json#/records/条目-0042/value",
  "id": "sanguo-faction-liubei",
  "scope": "同一现行基础条目；原作出处、时代和GM知情范围仍按所引条目，不额外授予玩家知识。"
 },
 "source_layer": "ORIGINAL_EARLY_PHASE_CONTEXT",
 "source_refs": [
  "SG8-H32",
  "SG8-H36"
 ],
 "phase_split": "早期义从与后来州郡军政分开；实际到了任职阶段再核范围，不按年份自动建蜀汉。",
 "representatives": [
  "sanguo-person-liubei",
  "sanguo-person-guanyu",
  "sanguo-person-zhangfei"
 ],
 "representative_rule": "刘备谋立足，关羽在意已许交接，张飞要眼前人手能守住；亲近仍可对等候、撤离、器具损坏有不同判断。",
 "goal_and_conflict": "保住愿追随的实际人手，取得能持续立足的支持；依附他人可换短期安全，也受对方目的和供给制约。",
 "resources_access": "按三张人物面向中的真实驻处与联系人接触。只有已登记单位、人手和私物可用，不把关张本人能力兑换成无穷兵，不把同行家属作为部队资源。",
 "autonomous_action": "无玩家时仍会按真实伤疲、路况和接纳回话迁动、停留或散去，留下未交接事项；不在原地无限等新玩家。",
 "changes": [
  {
   "when": "接纳落实且同行者愿行",
   "effect": "迁往实到的新处，原地点只留下能被查到的去向，不生成多处同一核心人物。"
  },
  {
   "when": "供应断绝或意见分歧未解决",
   "effect": "缩小行动、分开走或重新依附，具体人不自动叛变；玩家可留普通往来，无强制结义。"
  }
 ],
 "common_condition_refs": [
  {
   "content_ref": "数据/世界资料.json#/records/SG-SCOPED-COMMON-01/value",
   "scope": "仅本条及所列同源条目共同适用。"
  }
 ]
}

