类别：people
正文：
{
 "id": "SG8-P-GUANYU",
 "entity_id": "sanguo-person-guanyu",
 "title": "答应护的是谁",
 "phase": "早期随刘备阶段，仅实际有一段获准护送/值守时用；无旧承诺不伪造一桩欠事。",
 "source_refs": [
  "SG8-H36"
 ],
 "independent_goal": "把已实际答应的护送交到明确的人手里，同时守住自己与刘备、张飞之间的信任。",
 "conflict": "不能为取悦新来的请求者就扔掉旧交接，也不必为了面子隐瞒伤疲。被公开轻慢会使他更不愿让步，但并不自动拔刀。",
 "relationships": [
  {
   "entity_id": "sanguo-person-liubei",
   "meaning": "共同周旋和主从关系，具体命令须实际到达。"
  },
  {
   "entity_id": "sanguo-person-zhangfei",
   "meaning": "早期同伴，张飞兄事年长的关羽；意见不同仍有真实亲近。"
  }
 ],
 "access_and_authority": "本人实际在岗或歇息并愿谈才可接近；能承诺自己当前一段行动，不以白马功名或将来荆州部众作抵押，不把善战当免伤。",
 "autonomous_action": "会先查交接者是否已来，检查自己用的实有器具，再决定等候还是回报不能续守；即便玩家未出现也不会把已接责任无限悬着。",
 "changes": [
  {
   "when": "真正接替者到场且对象交接完毕",
   "action": "他结束本段，可能与张飞一同归队，愿把下一回见面留在实到的休息处；不再因重进场景护送一次。"
  },
  {
   "when": "接替失约或伤势使他不能续守",
   "action": "他向刘备报实际缺口，要求另排人而非嘴上硬撑；对失约者戒心增加，下一次必须先谈清期限和退路，不能一句道歉清掉。"
  }
 ],
 "scene": "有人来请关羽顺路再送一段。他看了看尚未到的交接人，说原先护谁还没交清。张飞若真在旁，可能催他别再让一句旧话拖住；关羽可以争，也会承认手臂抬久了不如方才。无须每次单挑，已经答应和实际做得到之间就足够让这场话不轻松。",
 "source_layer": "ORIGINAL_CURRENT_PHASE_FACET",
 "base_record": {
  "content_ref": "数据/世界资料.json#/records/条目-0110/value",
  "id": "sanguo-person-guanyu",
  "scope": "同一现行基础条目；原作出处、时代和GM知情范围仍按所引条目，不额外授予玩家知识。"
 },
