原ID：SG8-P-ZHANGFEI
类别：people
正文：
{
 "id": "SG8-P-ZHANGFEI",
 "entity_id": "sanguo-person-zhangfei",
 "title": "夜里没人敢说的损坏",
 "phase": "早期随刘备，已确有守夜交接或器具检查时；后来严刑与遇害只作作者后期资料，不在190自动重演。",
 "source_refs": [
  "SG8-H36"
 ],
 "independent_goal": "让今晚实际担任守夜的人能顶住差事，不把有损坏的器具交到下一班才发现。",
 "conflict": "催促和威势能使人立刻动手，也会使人不敢报坏；他想快办，又不喜欢听自己把问题压下去。不能把他改写成每次都温和认错。",
 "relationships": [
  {
   "entity_id": "sanguo-person-liubei",
   "meaning": "随从与受命的联系，关切能否让同伴带着实际人手完成任务。"
  },
  {
   "entity_id": "sanguo-person-guanyu",
   "meaning": "兄事关羽，亲近不等于每次赞同他的等候与交接办法。"
  }
 ],
 "access_and_authority": "在真实当班地点通过当班者接触；只能调他实有且获准的人和器材。无部曲实例时只谈本人协作，不从后期万人之敌造出万人。",
 "autonomous_action": "玩家没来，他也会查下一班谁接、哪件东西不能用。若有人一直支吾，他可能亲手试器具、逼问责任，使汇报者更畏惧；这是真实性格风险，不由系统替他悔过。",
 "changes": [
  {
   "when": "损坏证据可靠并有人能修或换",
   "action": "他可让实有器具替换、减去不能做的巡段；愿意听这次直话不等于脾气永久改变，下次仍会追问谁验过。"
  },
  {
   "when": "因催压而隐瞒的问题在夜里暴露",
   "action": "真实漏守、伤疲或器材损失留存，他与报告者的关系可能更紧张；刘备或关羽若确已知情可提出异议，玩家不能一段劝说清零后果。"
  }
 ],
 "scene": "坏的那件东西放到面前，张飞先问为何白天不说。有人若回答“说了怕挨骂”，场面未必因此变成认错会。他可能压着怒气先换器材，也可能先追究人。玩家可以给出证据、拒作虚假背书或退出；值夜的人之后还要相处，那份胆怯也不会因拿到任务奖励便消失。",
 "source_layer": "ORIGINAL_CURRENT_PHASE_FACET",
 "base_record": {
  "content_ref": "数据/世界资料.json#/records/条目-0115/value",
  "id": "sanguo-person-zhangfei",
  "scope": "同一现行基础条目；原作出处、时代和GM知情范围仍按所引条目，不额外授予玩家知识。"
 },
